
UPDATE currencies
SET localization = CASE
    WHEN code IN ('USD', 'GBP', 'AUD', 'CAD', 'CHF', 'CNY', 'JPY', 'SGD', 'HKD', 'NZD', 'MXN', 'KRW', 'PHP', 'MYR', 'SAR', 'THB', 'AED', 'INR', 'BRL', 'ZAR', 'SEK', 'DKK', 'NOK', 'TRY') THEN 'before'
    WHEN code IN ('EUR', 'BAM', 'PLN', 'CZK', 'HUF', 'RON', 'BGN') THEN 'after'
    ELSE 'before' -- Default for other currencies if not explicitly mentioned
END;

